import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
const require = createRequire(`${process.env.RUNNER_TEMP}/vox-browser/package.json`);
const { chromium } = require('playwright');
const base = 'http://127.0.0.1:3196';
const browser = await chromium.launch({ headless: true });
try {
  for (const width of [390, 1440]) {
    const page = await browser.newPage({ viewport: { width, height: 900 } });
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await page.goto(base);
    const headerSearch = page.getByRole('textbox', { name: 'Pesquisar no catálogo', exact: true });
    await headerSearch.fill('produto ausente');
    await page.getByText('Nenhum produto corresponde aos filtros.').waitFor();
    await headerSearch.fill('ci product');
    assert.equal(await page.getByRole('textbox', { name: 'Buscar produtos', exact: true }).inputValue(), 'ci product');
    if (width === 390) {
      assert.equal(await page.getByRole('navigation', { name: 'Navegação inferior' }).isVisible(), true);
      await page.getByRole('button', { name: 'Abrir menu' }).click();
      await page.getByRole('navigation', { name: 'Menu mobile' }).getByRole('link', { name: 'Produtos', exact: true }).click();
    }
    assert.equal(await page.getByRole('link', { name: 'Painel do lojista', exact: true }).getAttribute('href'), '/admin/login');
    const search = page.getByRole('textbox', { name: 'Buscar produtos' });
    await search.fill('ci product');
    const card = page.locator('.product-card');
    await card.first().waitFor();
    assert.equal(await card.count(), 1);
    await search.fill('não existe esse produto');
    await page.getByText('Nenhum produto corresponde aos filtros.').waitFor();
    await page.getByRole('button', { name: 'Limpar filtros' }).click();
    await card.first().waitFor();
    await page.getByRole('checkbox', { name: 'Disponíveis em estoque' }).check();
    await page.getByRole('combobox', { name: 'Ordenar produtos' }).selectOption('menor');
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true, `No horizontal overflow at ${width}px`);
    await card.first().getByRole('button', { name: 'Ver detalhes de CI product' }).click();
    await page.getByRole('heading', { name: 'CI product', exact: true, level: 2 }).waitFor();
    assert.equal(errors.length, 0, errors.join('\n'));
    await page.close();
  }
  const page = await browser.newPage();
  const response = await page.request.post(`${base}/api/auth/login`, { data: { email: 'ci-admin@example.com', senha: 'ci-admin-password-only-123' } });
  const admin = await response.json();
  await page.addInitScript(user => localStorage.setItem('vox_user', JSON.stringify(user)), { ...admin.user, token: admin.token });
  await page.goto(`${base}/admin/produtos`);
  await page.getByRole('button', { name: 'Novo produto', exact: true }).click();
  await page.getByLabel('Nome do produto', { exact: true }).fill('CI Guided Product');
  await page.getByLabel('Descrição', { exact: true }).fill('Produto criado pelo fluxo guiado real');
  await page.getByLabel('Foto do produto').setInputFiles({ name: 'ci.svg', mimeType: 'image/svg+xml', buffer: Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="180" height="120"><rect width="180" height="120" fill="#0825a3"/></svg>') });
  await page.getByRole('button', { name: 'Ajustar imagem', exact: true }).waitFor();
  await page.getByRole('button', { name: 'Continuar', exact: true }).click();
  await page.getByLabel('Preço atual (R$)', { exact: true }).fill('199.90');
  await page.getByLabel('Estoque disponível', { exact: true }).fill('3');
  await page.getByRole('button', { name: 'Continuar', exact: true }).click();
  await page.getByRole('button', { name: 'Cadastrar produto', exact: true }).click();
  await page.getByRole('dialog', { name: 'Produto', exact: true }).waitFor({ state: 'hidden' });
  await page.getByText('CI Guided Product', { exact: true }).waitFor();
  const products = await (await page.request.get(`${base}/api/produtos/admin`, { headers: { Authorization: `Bearer ${admin.token}` } })).json();
  const guidedProduct = products.find(p => p.nome === 'CI Guided Product');
  assert.equal(guidedProduct.preco, 199.90);
  assert.equal(guidedProduct.estoque, 3);
  assert.match(guidedProduct.imgUrl, /\.webp$/);
  assert.equal((await page.request.get(base + guidedProduct.imgUrl)).status(), 200);
  await page.goto(`${base}/admin/produtos?estoque=baixo&busca=CI%20Guided`);
  await page.getByRole('button', { name: 'Editar', exact: true }).click();
  await page.getByRole('button', { name: 'Continuar', exact: true }).click();
  await page.getByLabel('Estoque disponível', { exact: true }).fill('12');
  await page.getByRole('button', { name: 'Continuar', exact: true }).click();
  await page.getByRole('button', { name: 'Salvar alterações', exact: true }).click();
  await page.getByRole('dialog', { name: 'Produto', exact: true }).waitFor({ state: 'hidden' });
  await page.getByRole('button', { name: 'Limpar filtros', exact: true }).waitFor();
  const updatedProduct = await (await page.request.get(`${base}/api/produtos/admin`, { headers: { Authorization: `Bearer ${admin.token}` } })).json();
  assert.equal(updatedProduct.find(p => p.id === guidedProduct.id).estoque, 12);
  assert.equal(updatedProduct.find(p => p.id === guidedProduct.id).imgUrl, guidedProduct.imgUrl, 'Editing stock preserves uploaded photo');
  await page.goto(`${base}/admin/pedidos`);
  await page.getByPlaceholder('Buscar pedido ou cliente…').fill('CI-1999');
  await page.getByRole('cell', { name: 'CI-1999', exact: true }).waitFor();
  assert.equal(await page.locator('tbody tr').count(), 1);
  await page.goto(`${base}/admin/configuracoes?secao=contact`);
  await page.locator('input[name="horarioSemana"]').fill('Seg–Sex 9h–18h CI');
  await page.getByRole('button', { name: 'Salvar configurações' }).click();
  await page.getByRole('button', { name: 'Salvo!' }).waitFor();
  await page.getByRole('tab', { name: 'Banner principal', exact: true }).click();
  await page.getByLabel('Título', { exact: true }).fill('CI landing editor real');
  await page.getByLabel('Enviar Imagem', { exact: true }).setInputFiles({ name: 'ci-hero.png', mimeType: 'image/png', buffer: Buffer.from('iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAIAAACQkWg2AAAACXBIWXMAAAPoAAAD6AG1e1JrAAAAGUlEQVQokWNgMDlJGmIY1XByNJRMhmnSAAC4rv0BDv2fxwAAAABJRU5ErkJggg==', 'base64') });
  await page.waitForFunction(() => document.querySelector('#editor-hero-image')?.value.startsWith('/uploads/landing/'));
  const livePreview = page.frameLocator('iframe[title="Prévia real da landing page"]');
  console.log('EDITOR PREVIEW DIAGNOSTIC', JSON.stringify(await page.locator('iframe').evaluate(el => ({ src: el.src, width: el.contentWindow.innerWidth, text: el.contentDocument.body.innerText.slice(0, 300) }))));
  await livePreview.getByRole('heading', { name: 'CI landing editor real', exact: true }).waitFor();
  const beforeEditorSave = await (await page.request.get(`${base}/api/loja`)).json();
  assert.notEqual(beforeEditorSave.config.landingPage.hero.title, 'CI landing editor real', 'Live preview cannot publish unsaved edits');
  await page.getByRole('button', { name: 'Salvar configurações', exact: true }).click();
  await page.getByRole('button', { name: 'Salvo!', exact: true }).waitFor();
  await page.reload();
  await livePreview.getByRole('heading', { name: 'CI landing editor real', exact: true }).waitFor();
  const savedLanding = await (await page.request.get(`${base}/api/loja`)).json();
  assert.match(savedLanding.config.landingPage.hero.image, /^\/uploads\/landing\/.+\.webp$/);
  assert.equal((await page.request.get(base + savedLanding.config.landingPage.hero.image)).status(), 200);
  await page.goto(base);
  await page.getByRole('heading', { name: 'CI landing editor real', exact: true }).waitFor();
  await page.getByText('Seg–Sex 9h–18h CI', { exact: false }).first().waitFor();
  await page.goto(`${base}/admin/conta`);
  await page.getByLabel('Senha atual', { exact: true }).fill('ci-admin-password-only-123');
  await page.getByLabel('Nova senha', { exact: true }).fill('ci-browser-admin-password');
  await page.getByLabel('Confirmar nova senha', { exact: true }).fill('ci-browser-admin-password');
  await page.getByRole('button', { name: 'Alterar senha', exact: true }).click();
  await page.getByText('Senha alterada com sucesso.', { exact: true }).waitFor();
  const customerPage = await browser.newPage();
  await customerPage.goto(`${base}/area-cliente/login`);
  await customerPage.getByRole('button', { name: 'Criar conta grátis' }).click();
  await customerPage.getByLabel('Nome', { exact: true }).fill('CI Browser Customer');
  await customerPage.locator('input[type="email"]').fill('ci-browser-customer@example.com');
  await customerPage.locator('input[type="password"]').fill('ci-browser-password-123');
  await customerPage.getByText('Adicionar telefone (opcional)', { exact: true }).click();
  await customerPage.getByLabel('Telefone para contato').fill('42991031420');
  await customerPage.getByRole('button', { name: 'Criar minha conta' }).click();
  await customerPage.waitForURL(`${base}/area-cliente`);
  await customerPage.goto(`${base}/area-cliente/fidelidade`);
  await customerPage.getByText('SEU SALDO', { exact: true }).waitFor();
  await customerPage.goto(`${base}/area-cliente/conta`);
  await customerPage.getByLabel('Senha atual', { exact: true }).fill('ci-browser-password-123');
  await customerPage.getByLabel('Nova senha', { exact: true }).fill('ci-browser-new-password');
  await customerPage.getByLabel('Confirmar nova senha', { exact: true }).fill('ci-browser-new-password');
  await customerPage.getByRole('button', { name: 'Alterar senha', exact: true }).click();
  await customerPage.getByText('Senha alterada com sucesso.', { exact: true }).waitFor();
  const customerLogin = await (await customerPage.request.post(`${base}/api/auth/login`, { data: { email: 'ci-browser-customer@example.com', senha: 'ci-browser-new-password' } })).json();
  const customerProfile = await (await customerPage.request.get(`${base}/api/auth/me`, { headers: { Authorization: `Bearer ${customerLogin.token}` } })).json();
  assert.equal(customerProfile.cliente.telefone, '42991031420');
  assert.equal((await customerPage.request.get(`${base}/api/produtos/admin`, { headers: { Authorization: `Bearer ${customerLogin.token}` } })).status(), 403);
  console.log('PASS: real catalog, guided product creation/editing and persisted WebP, contextual stock filters, customer contact registration and shared password change, order search, saved public hours, roles and mobile/desktop.');
} finally {
  await browser.close();
}
